templates.template:
/* =============================================================================
   Flourish — a XenForo 2.3 port of the ProBoards v4 "Flourish" skin by Silent of IncrediBAD.
   Black-to-grey page, white rounded content box, silver title bars, rainbow category
   bars and rainbow-stripe forum icons. The skin's images are embedded below, so the
   style needs no uploads.
   ============================================================================= */

// ---- Logo ----------------------------------------------------------------------
// The original rainbow "flourish" logo was a hosted image that isn't in the skin package,
// so it's drawn here as rainbow text. Change the word on the next line to your board's
// name, or delete this whole "Logo" section to use the logo image set in Style properties.
@flourish-logo-text: "flourish";

.p-header-logo
{
	a
	{
		display: inline-block;
		text-decoration: none;
	}

	img
	{
		display: none;
	}

	a::after
	{
		content: @flourish-logo-text;
		display: block;
		font-family: 'Comfortaa', 'Varela Round', 'Arial Rounded MT Bold', 'Nunito', 'Trebuchet MS', sans-serif;
		font-size: 64px;
		font-weight: 700;
		letter-spacing: -2px;
		line-height: 1;
		background: linear-gradient(90deg, #ff2a2a 0%, #ffd400 18%, #2bff2b 34%, #ff8c00 50%, #ff2a8c 66%, #c42bff 82%, #2a4bff 100%);
		-webkit-background-clip: text;
		background-clip: text;
		color: transparent;
		filter: drop-shadow(0 2px 3px rgba(0, 0, 0, .6));
	}
}

@media (max-width: @xf-responsiveNarrow)
{
	.p-header-logo a::after
	{
		font-size: 44px;
	}
}

// ---- Page: black fading to charcoal ----------------------------------------------

html
{
	min-height: 100%;
	background: linear-gradient(180deg, #000 0, #242424 300px, #4e4e4e 600px, #575757 900px) no-repeat #575757;
}

body
{
	background: transparent;
}

.p-pageWrapper
{
	background: transparent;
}

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 1000px;
}

.p-header
{
	background: transparent;
	color: #fff;
}

.p-header-content
{
	padding: 30px 0 0;
}

// ---- White content box with rounded corners and a dark shadow ---------------------
// The nav row is its top, the body its middle and the copyright line its bottom.

.p-nav
{
	background: transparent;
	color: #340000;
}

.p-nav-inner
{
	background: #fff;
	border-radius: 6px 6px 0 0;
	padding: 24px 10px 0;
	box-shadow: 4px 0 6px rgba(0, 0, 0, .55);
}

// Silver navigation bar inside the box
.p-nav-scroller
{
	background: linear-gradient(180deg, #dadada 0%, #e8e8e8 50%, #f6f6f6 100%);
	border: 1px solid #d3d3d3;
	box-shadow: inset 0 1px 0 #e8e8e8;
}

.p-nav-list
{
	justify-content: center;
	width: 100%;

	.p-navEl
	{
		background: transparent;
	}

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: #340000;
		font-weight: 700;
		font-size: 11px;

		&:hover
		{
			color: #7a1fa2;
			text-decoration: none;
		}
	}

	.p-navEl.is-selected
	{
		background: rgba(0, 0, 0, .06);

		.p-navEl-link
		{
			color: #000;
		}
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link
{
	color: #340000;

	&:hover
	{
		background: rgba(0, 0, 0, .06);
		color: #7a1fa2;
		text-decoration: none;
	}
}

.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: #340000;
}

.p-sectionLinks
{
	background: transparent;
	border: none;
}

.p-sectionLinks-inner
{
	background: #fff;
	padding: 0 10px;
	box-shadow: 4px 0 6px rgba(0, 0, 0, .55);

	.hScroller-scroll
	{
		border-bottom: 1px solid #d3d3d3;
	}

	a
	{
		color: #340000;
	}
}

.p-body
{
	background: transparent;
}

.p-body-inner
{
	background: #fff;
	padding: 10px 10px 20px;
	border-radius: 0 0 6px 6px;
	box-shadow: 4px 4px 6px rgba(0, 0, 0, .55);
}

@media (max-width: @xf-responsiveWide)
{
	.p-nav-inner,
	.p-sectionLinks-inner,
	.p-body-inner
	{
		border-radius: 0;
		box-shadow: none;
	}
}

.p-breadcrumbs
{
	font-size: 11px;
}

// ---- Blocks: black-bordered tables ---------------------------------------------

.block-container
{
	border: 1px solid #000;
	border-radius: 0;
}

// Rainbow category bars (forum categories and block titles)
.block-header
{
	background: url("data:image/jpeg;base64,") center / 100% 100% no-repeat, linear-gradient(90deg, #4b781d, #783c17, #7b174d, #5a257f);
	border-bottom: 1px solid #000;
	color: #fff;
	font-weight: 700;
	text-shadow: 1px 1px 1px rgba(0, 0, 0, .7);

	a,
	a:hover
	{
		color: #fff;
	}

	.block-desc
	{
		color: rgba(255, 255, 255, .85);
	}
}

// Silver title rows ("Forum Name", "Info Center", sidebar block titles)
.block-minorHeader,
.block-tabHeader,
.menu-tabHeader,
.menu-header,
.block-filterBar,
.dataList-row--header .dataList-cell
{
	background: linear-gradient(180deg, #dadada 0%, #e8e8e8 50%, #f6f6f6 100%);
	border-bottom: 1px solid #000;
	color: #340000;
	font-weight: 700;
	text-shadow: none;

	a
	{
		color: #340000;
	}
}

.block-tabHeader .tabs-tab,
.menu-tabHeader .tabs-tab
{
	color: #555;

	&:hover
	{
		color: #7a1fa2;
	}

	&.is-active
	{
		color: #340000;
		border-color: #7a1fa2;
	}
}

.block-footer
{
	background: url("data:image/jpeg;base64,") center / 100% 100% no-repeat, #5a257f;
	border-top: 1px solid #000;
	color: #fff;

	a
	{
		color: #fff;
	}
}

// ---- Forum list rows ---------------------------------------------------------

.node + .node
{
	border-top: 1px solid #000;
}

.node-body
{
	background: #f6f6f6;
}

.node-main,
.node-stats
{
	border-right: 1px solid #000;
}

.node-title a
{
	color: #340000;
	font-weight: 700;

	&:hover
	{
		color: #7a1fa2;
	}
}

.node-description,
.node-meta
{
	color: #340000;
	font-size: 11px;
}

// Rainbow-stripe forum icons: bright when there are new posts, faded when read.
// Links, pages and categories keep their normal icons.
.node-icon
{
	border-right: 1px solid #000;
}

.node--forum .node-icon i
{
	display: block;
	width: 32px;
	height: 32px;
	margin: 0 auto;
	background: url("data:image/png;base64,") center / 32px 32px no-repeat;

	svg,
	&::before
	{
		display: none;
	}
}

.node--forum.node--unread .node-icon i
{
	background-image: url("data:image/png;base64,");
}

.node--link,
.node--page,
.node--category
{
	.node-icon i
	{
		color: #7a1fa2;
	}
}

// ---- Thread lists and posts ------------------------------------------------------

.structItem
{
	background: #f6f6f6;
	border-top-color: #000;
}

.structItem-title a
{
	color: #340000;
	font-weight: 700;

	&:hover
	{
		color: #7a1fa2;
	}
}

.message
{
	border-color: #000;
}

.message-cell--user
{
	background: linear-gradient(180deg, #f6f6f6 0%, #ececec 100%);
	border-right-color: #000;
}

.message-name a
{
	color: #340000;
}

// ---- Buttons -----------------------------------------------------------------

.button.button--primary,
a.button.button--primary
{
	background: linear-gradient(180deg, #8a35b8 0%, #5a257f 100%);
	border: 1px solid #3d1857;
	color: #fff;

	&:hover
	{
		background: linear-gradient(180deg, #9d45cc 0%, #6a2c93 100%);
		color: #fff;
	}
}

// ---- Footer: copyright line on the grey page, then the skin credit ------------------

.p-footer
{
	background: transparent;
	color: #ccc;

	a
	{
		color: #ddd;

		&:hover
		{
			color: #fff;
		}
	}
}

.p-footer-copyright::after
{
	content: "Flourish skin by Silent of IncrediBAD";
	display: block;
	margin-top: 4px;
	font-weight: 700;
	background: linear-gradient(90deg, #c42bff, #2a4bff, #2bff2b, #ffd400);
	-webkit-background-clip: text;
	background-clip: text;
	color: transparent;
}
